<!DOCTYPE html>
<html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><link rel="stylesheet" href="../style/style.css"><title>Marketplace : Panier</title></head>
<body><header class="site-header"><a class="brand" href="catalog_html.php">Marché local</a><nav><a href="catalog_html.php">Catalogue</a><a href="cart_html.php">Panier</a><a href="../orders/orders_html.php">Mes commandes</a><a href="../auth/logout.php">Déconnexion</a></nav></header>
<main><div class="hero-copy"><p class="eyebrow">Votre sélection</p><h1>Votre panier.</h1></div><div id="cart"></div></main>
<script>
const cart = document.getElementById('cart');
function escapeHtml(value) { return String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[char])); }
async function loadCart() { const response = await fetch('cart_php.php'); const data = await response.json(); if (data.login) { location.href='../auth/login_html.php'; return; } if (!data.items.length) { cart.innerHTML='<div class="empty">Votre panier est vide. <a class="link" href="catalog_html.php">Voir le catalogue</a></div>'; return; } cart.innerHTML = `<div class="table-wrap"><table><thead><tr><th>Produit</th><th>Prix</th><th>Quantité</th><th>Sous-total</th><th></th></tr></thead><tbody>${data.items.map(item => `<tr><td>${escapeHtml(item.product_name)}</td><td>${Number(item.product_price).toFixed(2)} €</td><td><input class="quantity" data-id="${item.id}" type="number" min="1" value="${item.quantity}" style="max-width:90px"></td><td>${Number(item.subtotal).toFixed(2)} €</td><td><button class="btn danger remove" data-id="${item.id}">Supprimer</button></td></tr>`).join('')}</tbody></table></div><div class="toolbar" style="justify-content:flex-end;align-items:center;margin-top:22px"><strong>Total : ${Number(data.total).toFixed(2)} €</strong><button class="btn" id="checkout">Passer la commande</button></div>`; document.querySelectorAll('.quantity').forEach(input => input.addEventListener('change', () => update({action:'update', id:input.dataset.id, quantity:input.value}))); document.querySelectorAll('.remove').forEach(button => button.addEventListener('click', () => update({action:'remove', id:button.dataset.id}))); document.getElementById('checkout').addEventListener('click', checkout); }
async function update(payload) { await fetch('cart_php.php', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(payload)}); loadCart(); }
async function checkout() { const response = await fetch('../orders/checkout_php.php', {method:'POST'}); const data = await response.json(); if (data.success) location.href='../orders/orders_html.php'; else alert(data.message); }
loadCart();
</script></body></html>
